    let a = 1000000;
    let (a0, a1) = decompose(a, alpha);
    assert!(a0 > -(GAMMA2 as i32) && a0 <= GAMMA2 as i32);
    assert_eq!(
        (a1 as i32 * alpha as i32 + a0) % DILITHIUM_Q as i32,
        (a % DILITHIUM_Q) as i32
    );

    // Test case 3: Boundary case (a such that a - a0 = q - 1)
