        let r0 = lowbits(r, alpha);

        // Check reconstruction
        let reconstructed =
            (((r1 as i64 * alpha as i64) + r0 as i64).rem_euclid(DILITHIUM_Q as i64)) as u32;
        assert_eq!(reconstructed, r % DILITHIUM_Q);

        // Check ranges
