//! Error registry for compatibility with deferred error handling APIs.
#[cfg(feature = "std")]
use core::any::Any;
#[cfg(not(feature = "std"))]
use core::sync::atomic::{AtomicBool, Ordering};
#[cfg(feature = "std")]
use std::boxed::Box;
#[cfg(feature = "std")]
use std::sync::{Mutex, MutexGuard};
/// Global error registry for recording the most recent deferred error.
///
/// The registry is retained for API compatibility. Prefer returning errors to
/// the caller directly: a process-global "last error" can be overwritten by an
/// unrelated operation at any time.
/// A synchronized, type-checked registry for a single error value.
///
/// Under `std`, stored errors are owned by a `Mutex` and retrieved using a
/// checked [`core::any::Any`] downcast. A request for a different type returns
/// `None`. Under `no_std`, where this crate has no synchronization primitive
/// capable of owning an arbitrary allocation, the registry records only
/// whether an error occurred.
    #[cfg(feature = "std")]
    state: Mutex<RegistryState>,
    #[cfg(not(feature = "std"))]
    has_error: AtomicBool,
}

#[cfg(feature = "std")]
struct RegistryState {
    error: Option<Box<dyn Any + Send>>,
    generation: u64,
    /// Create a new, empty error registry.
            #[cfg(feature = "std")]
            state: Mutex::new(RegistryState {
                error: None,
                generation: 0,
            }),
            #[cfg(not(feature = "std"))]
            has_error: AtomicBool::new(false),
    /// Store an error in the registry, replacing the previous value.
    ///
    /// Errors must be owned and safe to move between threads because the
    /// registry is process-global. The replaced value is dropped after the
    /// registry lock is released so user-defined destructors cannot deadlock
    /// the registry by re-entering it.
    pub fn store<E>(&self, error: E)
    where
        E: Send + 'static,
    {
            let old = {
                let mut state = self.lock();
                state.generation = state.generation.wrapping_add(1);
                state.error.replace(Box::new(error))
            };
            drop(old);
            drop(error);
            self.has_error.store(true, Ordering::Release);
    /// Clear and drop the stored error, if any.
            let old = {
                let mut state = self.lock();
                state.generation = state.generation.wrapping_add(1);
                state.error.take()
            };
            drop(old);
        self.has_error.store(false, Ordering::Release);
    /// Check whether an error is currently present.
        #[cfg(feature = "std")]
        {
            self.lock().error.is_some()
        }

        #[cfg(not(feature = "std"))]
        {
            self.has_error.load(Ordering::Acquire)
        }
    /// Clone the stored error if its concrete type is exactly `E`.
    ///
    /// A type mismatch returns `None`; callers can never reinterpret the
    /// allocation as another type.
    pub fn get_error<E>(&self) -> Option<E>
    where
        E: Clone + Send + 'static,
    {
        // Temporarily remove the allocation so user-defined `Clone` code runs
        // without the registry mutex held. If another operation mutates the
        // registry while cloning, that newer operation wins and the old value
        // is dropped instead of being restored.
        let (stored, generation) = {
            let mut state = self.lock();
            let stored = state.error.take()?;
            (stored, state.generation)
        };

        let cloned = stored.downcast_ref::<E>().cloned();

        let displaced = {
            let mut state = self.lock();
            if state.generation == generation && state.error.is_none() {
                state.error = Some(stored);
                None
            } else {
                Some(stored)
        };
        drop(displaced);

        cloned
    }

    #[cfg(feature = "std")]
    fn lock(&self) -> MutexGuard<'_, RegistryState> {
        // A panic in a user-provided Clone implementation can poison the
        // mutex. Poisoning does not make the owned value unsafe, so recover the
        // guard and keep the registry usable.
        self.state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)

    /// Return the secret bytes as a slice.
    pub fn as_slice(&self) -> &[u8] {
        &self.data
    }

    /// Return the secret bytes as a mutable slice.
    ///
    /// Slice access permits in-place byte changes but cannot resize or
    /// reallocate the backing storage.
    pub fn as_mut_slice(&mut self) -> &mut [u8] {
        &mut self.data
    }

    /// Return the allocation capacity.
    pub fn capacity(&self) -> usize {
        self.data.capacity()
    }

    /// Extend the value, wiping the old allocation before freeing it if growth
    /// requires a larger allocation.
    pub fn extend_from_slice(&mut self, slice: &[u8]) {
        self.ensure_additional_capacity(slice.len());
        self.data.extend_from_slice(slice);
    }

    /// Resize the value. Bytes removed by shrinking are wiped first.
    pub fn resize(&mut self, new_len: usize, value: u8) {
        if new_len <= self.data.len() {
            self.truncate(new_len);
            return;
        }

        self.ensure_additional_capacity(new_len - self.data.len());
        self.data.resize(new_len, value);
    }

    /// Shorten the value, wiping every removed byte before changing its length.
    pub fn truncate(&mut self, len: usize) {
        if len >= self.data.len() {
            return;
        }

        self.data[len..].zeroize();
        self.data.truncate(len);
    }

    /// Remove all bytes while retaining a fully zeroed allocation.
    pub fn clear(&mut self) {
        self.data.zeroize();
    }

    /// Append one byte, securely replacing the allocation when it is full.
    pub fn push(&mut self, value: u8) {
        self.ensure_additional_capacity(1);
        self.data.push(value);
    }

    /// Remove and return the last byte, wiping its allocation slot first.
    pub fn pop(&mut self) -> Option<u8> {
        let value = self.data.last().copied()?;
        let new_len = self.data.len() - 1;
        self.data[new_len].zeroize();
        self.data.truncate(new_len);
        Some(value)
    }

    /// Reserve room for at least `additional` more bytes without resizing the
    /// live secret allocation in place.
    pub fn reserve(&mut self, additional: usize) {
        self.ensure_additional_capacity(additional);
    }

    /// Reduce capacity to the current length while wiping the old allocation.
    pub fn shrink_to_fit(&mut self) {
        if self.data.capacity() > self.data.len() {
            self.secure_reallocate(self.data.len());
        }
    }

    fn ensure_additional_capacity(&mut self, additional: usize) {
        let required = self
            .data
            .len()
            .checked_add(additional)
            .expect("SecretVec capacity overflow");

        if required > self.data.capacity() {
            self.secure_reallocate(required);
        }
    }

    fn secure_reallocate(&mut self, capacity: usize) {
        debug_assert!(capacity >= self.data.len());

        let mut replacement = Vec::with_capacity(capacity);
        replacement.extend_from_slice(&self.data);
        Self::zeroize_spare_capacity(&mut replacement);

        // Vec::zeroize wipes both its initialized bytes and its entire spare
        // capacity. Free the allocation only after that wipe is complete.
        self.data.zeroize();
        #[cfg(test)]
        assert!(Self::allocation_is_zeroed(&self.data));
        self.data = replacement;
    }

    fn zeroize_spare_capacity(data: &mut Vec<u8>) {
        data.spare_capacity_mut().zeroize();
    }

    #[cfg(test)]
    fn allocation_is_zeroed(data: &Vec<u8>) -> bool {
        // Callers use this only after Vec::zeroize(), which initializes the
        // entire allocation with zero bytes and sets len to zero.
        let allocation = unsafe { core::slice::from_raw_parts(data.as_ptr(), data.capacity()) };
        allocation.iter().all(|byte| *byte == 0)
    }
}

