        make_hint_coeff(1, GAMMA2, 2 * GAMMA2),
        "Dilithium2: make_hint_coeff(1, γ₂) should be true per FIPS 204"
    );

    // Other boundary cases
    assert!(
        !make_hint_coeff(0, GAMMA2, 2 * GAMMA2),
        "Dilithium2: make_hint_coeff(0, γ₂) should be false"
    );

    assert!(
