struct BackshiftOnDrop<'vec, T, const CAP: usize> {
    vec: &'vec mut StackVec<T, CAP>,
    processed: usize,
    deleted: usize,
    original_len: usize,
}

impl<T, const CAP: usize> Drop for BackshiftOnDrop<'_, T, CAP> {
    fn drop(&mut self) {
